recipeCss:
:root{--background:#14231C;--surface:#1D3128;--surface-raised:#243B31;--text:#F3EFE4;--text-quiet:#C9C4B2;--accent:#FFC94A;--accent-ink:#14231C;--secondary:#7CC6A6;--edge:#6E8A7B;--radius:14px;--radius-small:10px;--font-display:'Fredoka',sans-serif;--font-body:'Atkinson Hyperlegible',system-ui,sans-serif}
html{background:var(--background);color:var(--text);font:400 16px/1.6 var(--font-body)}
h1,h2,h3{font-family:var(--font-display);font-weight:600;letter-spacing:-0.01em;line-height:1.12}
.btn-primary{background:var(--accent);color:var(--accent-ink);border:none;border-radius:var(--radius-small);min-height:48px;padding:10px 26px;font:600 18px var(--font-display);cursor:pointer}
.btn-primary:hover{background:#FFD56E}.btn-primary:active{background:#EAB335}
.btn-primary[aria-busy=true]{background:#EAB335;cursor:progress}
.btn-primary:disabled,[aria-disabled=true]{background:#3A5144;color:#8FA296;cursor:not-allowed}
.btn-secondary{background:transparent;color:var(--accent);border:2px solid var(--accent);border-radius:var(--radius-small);min-height:48px;padding:10px 20px;cursor:pointer}
.btn-secondary:hover{border-color:#FFD56E;color:#FFD56E}
.btn-secondary:active{background:rgba(255,201,74,.18);color:#FFD56E}
textarea,select,input{background:var(--surface-raised);color:var(--text);border:2px solid var(--edge);border-radius:var(--radius-small);padding:10px 12px;font:inherit;font-size:16px}
textarea:hover,select:hover,input:hover{border-color:var(--secondary)}
textarea:focus-visible,select:focus-visible,input:focus-visible{border-color:var(--accent);outline:none}
input[type=checkbox]:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
select{appearance:none}
input[type=range]{accent-color:var(--accent);min-height:44px}
input[type=checkbox]{accent-color:var(--accent);width:18px;height:18px}
svg[data-wheel]{cursor:pointer}
svg[data-wheel]:hover .wheelspin{filter:brightness(1.06)}
svg[data-wheel]:active .wheelspin{filter:brightness(.94)}
svg[data-wheel]:focus-visible{outline:3px solid var(--accent);outline-offset:4px;border-radius:50%}
.winner-spot{position:absolute;left:0;right:0;bottom:0;padding:18px 20px 22px;background:rgba(20,35,28,.92);border-radius:0 0 var(--radius) var(--radius);text-align:center}
.winner-spot .wname{font-family:var(--font-display);font-weight:600;font-size:clamp(34px,4.6vw,58px);line-height:1.05;color:var(--accent);word-break:break-word}
.winner-spot .wkeys{display:flex;gap:10px;justify-content:center;margin-top:12px;flex-wrap:wrap}
[data-state=winner] .wheelzone .winner-spot{display:block;animation:rise .3s ease-out}
@keyframes rise{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}
a:focus-visible,button:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
.quiet-link{color:var(--accent);text-decoration:underline;min-height:24px;display:inline-block}
@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
